// OrderService
@Transactional
public void placeOrder(Order order) {
    orderRepository.save(order);
    try {
        paymentAuditService.audit(order);   // REQUIRED, throws IllegalStateException
    } catch (RuntimeException e) {
        System.out.println("Audit failed");
    }
    System.out.println("Order completed");
}

// OrderService
@Transactional
public void placeOrder(Order order) {
    orderRepository.save(order);
    paymentAuditService.audit(order);   // REQUIRES_NEW: saves PaymentAudit(amount, order.getId(), true)
    throw new IllegalStateException("Payment gateway down");
}

@Service
public class OrderService {

    @Transactional
    public void placeOrder(Order order) {
        orderRepository.save(order);
        saveAudit(order);
        throw new IllegalStateException("Payment failed");
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void saveAudit(Order order) {
        paymentAuditRepository.save(
            new PaymentAudit(order.getAmount(), order.getId(), false));
    }
}
